Directory? _root;
Directory get root => _root!;
late FileMessagingRepository repo;
BridgeServer? _server;
HeadlessChrome? _chrome;

/// Non-null once setUpAll succeeded; tests only run after that.
BridgeServer get server => _server!;
HeadlessChrome get chrome => _chrome!;

void main() {
  setUpAll(() async {
    _root = await Directory.systemTemp.createTemp('fa-bridge-e2e-');
    // Real fabric layout: <sessionRoot>/<slug>/messages — a bare
    // <tmp>/messages would make the repo's session root the WHOLE /tmp and
    // any leftover <tmp>/x/messages/main/.id would hijack recipient routing.
    repo = FileMessagingRepository(
      env: LocalExecutionEnv(cwd: root.path),
      root: '${root.path}/proj/messages',
    );
    final token = [REDACTED:Sensitive Value] BridgeTokenFile(root.path).ensure();
    _server = BridgeServer(
      messaging: repo,
      root: root.path,
      token: [REDACTED:Sensitive Value],
