    final json = source.replaceAll(RegExp(r'^\s*//.*$', multiLine: true), '');
    final key = (jsonDecode(json) as Map<String, dynamic>)['key'] as String;
    final hex = sha256.convert(base64.decode(key)).toString();
    return hex
